package com.bombless.luaandroid.ipc.v2;
import android.os.Parcel; import android.os.Parcelable;
public final class CapabilityInfo implements Parcelable { public String id="",limits="{}";public int schemaVersion=1;public CapabilityInfo(){}private CapabilityInfo(Parcel p){id=p.readString();schemaVersion=p.readInt();limits=p.readString();}public void writeToParcel(Parcel p,int f){p.writeString(id);p.writeInt(schemaVersion);p.writeString(limits);}public int describeContents(){return 0;}public static final Creator<CapabilityInfo> CREATOR=new Creator<CapabilityInfo>(){public CapabilityInfo createFromParcel(Parcel p){return new CapabilityInfo(p);}public CapabilityInfo[] newArray(int n){return new CapabilityInfo[n];}}; }